import{_ as r,o as a,c as t,a3 as l}from"./chunks/framework.DBpCFmh2.js";const p=JSON.parse('{"title":"文档处理与解析","description":"本模块负责将多种格式的本地文档统一转换为纯文本，并进一步切分为适合嵌入检索的分块。","frontmatter":{"title":"文档处理与解析","description":"本模块负责将多种格式的本地文档统一转换为纯文本，并进一步切分为适合嵌入检索的分块。"},"headers":[],"relativePath":"系统架构设计/数据流设计/RAG-数据处理管道/文档处理与解析/index.md","filePath":"系统架构设计/数据流设计/RAG-数据处理管道/文档处理与解析/index.md","lastUpdated":null}'),i={name:"系统架构设计/数据流设计/RAG-数据处理管道/文档处理与解析/index.md"};function n(o,e,s,g,c,h){return a(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="文档处理与解析" tabindex="-1">文档处理与解析 <a class="header-anchor" href="#文档处理与解析" aria-label="Permalink to &quot;文档处理与解析&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/text.js" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/text.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/pdf.js" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/pdf.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/office.js" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/office.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js" target="_blank" rel="noreferrer">agent/src/rag/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js" target="_blank" rel="noreferrer">agent/src/rag/errors.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与内存优化">性能与内存优化</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录">附录</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本模块负责将多种格式的本地文档统一转换为纯文本，并进一步切分为适合嵌入检索的分块。其设计目标是：</p><ul><li>支持多格式加载：文本、HTML、PDF、Office（Word/Excel/PPT 等）。</li><li>通过扩展名路由到对应解析器，按需加载第三方依赖，降低冷启动成本。</li><li>提供稳定可控的文本分块算法，兼顾中文语义完整性与模型 token 上限。</li><li>使用结构化错误类型，便于上层进行国际化提示与恢复策略。</li></ul><p>该模块属于 Agent 端的 RAG 子系统，位于 <code>agent/src/rag/document</code> 下，由 loader 统一入口、parsers 多实现、chunker 分块逻辑组成，并通过 config 暴露配置项与扩展名路由表。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>RAG 文档处理相关代码集中在以下路径：</p><ul><li><code>agent/src/rag/document/loader.js</code>：按扩展名路由到解析器，统一输出 <code>{ text, fileName }</code>。</li><li><code>agent/src/rag/document/chunker.js</code>：段落优先 + 字符窗口兜底 + 重叠的分块算法。</li><li><code>agent/src/rag/document/parsers/text.js</code>：纯文本类格式（txt/md/json/csv）读取与 BOM 清理。</li><li><code>agent/src/rag/document/parsers/pdf.js</code>：基于 pdf-parse 的 PDF 文本提取。</li><li><code>agent/src/rag/document/parsers/office.js</code>：docx/xlsx/xls/pptx 等 Office 文档的多库组合解析。</li><li><code>agent/src/rag/config.js</code>：RAG 根目录、默认分块参数、解析器扩展名路由表等。</li><li><code>agent/src/rag/errors.js</code>：RAG 业务错误 RagError 及翻译辅助函数。</li></ul><pre class="mermaid">graph TB
subgraph &quot;RAG 文档处理&quot;
L[&quot;loader.js&lt;br/&gt;按扩展名路由&quot;]
C[&quot;chunker.js&lt;br/&gt;文本分块&quot;]
P_TXT[&quot;parsers/text.js&lt;br/&gt;纯文本&quot;]
P_PDF[&quot;parsers/pdf.js&lt;br/&gt;PDF&quot;]
P_OFFICE[&quot;parsers/office.js&lt;br/&gt;Office&quot;]
CFG[&quot;config.js&lt;br/&gt;路由表/默认配置&quot;]
ERR[&quot;errors.js&lt;br/&gt;RagError&quot;]
end
L --&gt; CFG
L --&gt; P_TXT
L --&gt; P_PDF
L --&gt; P_OFFICE
L --&gt; ERR
C --&gt; CFG
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-L76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/text.js#L1-L15" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/text.js#L1-L15</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/pdf.js#L1-L21" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/pdf.js#L1-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/office.js#L1-L56" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/office.js#L1-L56</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L1-L30</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-L76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L1-L70" target="_blank" rel="noreferrer">agent/src/rag/config.js#L1-L70</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li>文档加载器（loader）：根据文件扩展名选择解析器，动态 import 对应模块，返回统一结构。</li><li>解析器（parsers）：针对不同格式实现 parse(filePath) → Promise&lt;string&gt;。</li><li>分块器（chunker）：对纯文本执行段落优先切分，控制 chunkSize 与 overlap，保留原文偏移。</li><li>配置（config）：集中管理 RAG 根目录、默认分块参数、解析器扩展名路由表。</li><li>错误（errors）：定义 RagError 与 translateRagError，用于上层响应层国际化。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-L76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L37-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L37-L69</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L1-L30</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示从文件路径到最终分块的完整流程：loader 根据扩展名路由到具体 parser，parser 返回纯文本；随后 chunker 对文本进行分块，返回包含原文偏移的结构，供后续 BM25 混合检索使用。</p><pre class="mermaid">sequenceDiagram
participant Caller as &quot;调用方&quot;
participant Loader as &quot;loader.js&quot;
participant Parser as &quot;parsers/*&quot;
participant Chunker as &quot;chunker.js&quot;
Caller-&gt;&gt;Loader : loadDocument(filePath)
Loader-&gt;&gt;Loader : 根据扩展名查找路由
Loader-&gt;&gt;Parser : 动态导入并调用 parse(filePath)
Parser--&gt;&gt;Loader : 返回纯文本
Loader--&gt;&gt;Caller : { text, fileName }
Caller-&gt;&gt;Chunker : chunkText(text, options)
Chunker--&gt;&gt;Caller : chunks[]含 startPos/endPos
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L38-L48" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L38-L48</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L31-L74" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L31-L74</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="文档加载器-loader-js" tabindex="-1">文档加载器（loader.js） <a class="header-anchor" href="#文档加载器-loader-js" aria-label="Permalink to &quot;文档加载器（loader.js）&quot;">​</a></h3><ul><li>功能职责： <ul><li>判断是否受支持：isSupportedFile(filePath)。</li><li>列出支持的扩展名：supportedExtensions()。</li><li>加载并解析文档：loadDocument(filePath) → Promise&lt;{ text, fileName }&gt;。</li></ul></li><li>路由机制： <ul><li>通过 extname 获取扩展名，查 PARSER_ROUTES 得到解析器名称。</li><li>若未匹配，抛出 RagError(&#39;unsupportedFormat&#39;, { ext })。</li></ul></li><li>按需加载： <ul><li>PARSERS 映射为延迟 import 函数，仅当实际用到对应格式时才加载依赖，减少冷启动开销。</li></ul></li><li>返回值： <ul><li>统一返回 { text, fileName }，fileName 取自 basename(filePath)。</li></ul></li></ul><pre class="mermaid">flowchart TD
Start([&quot;开始&quot;]) --&gt; GetExt[&quot;获取扩展名&quot;]
GetExt --&gt; CheckRoute{&quot;是否在路由表中？&quot;}
CheckRoute --&gt; |否| ThrowErr[&quot;抛出 RagError(&#39;unsupportedFormat&#39;)&quot;]
CheckRoute --&gt; |是| LazyImport[&quot;动态 import 对应解析器&quot;]
LazyImport --&gt; CallParse[&quot;调用 parse(filePath)&quot;]
CallParse --&gt; ReturnObj[&quot;返回 { text, fileName }&quot;]
ThrowErr --&gt; End([&quot;结束&quot;])
ReturnObj --&gt; End
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L21-L48" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L21-L48</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L5-L16" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L5-L16</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L1-L30</a></li></ul><h3 id="解析器-parsers" tabindex="-1">解析器（parsers） <a class="header-anchor" href="#解析器-parsers" aria-label="Permalink to &quot;解析器（parsers）&quot;">​</a></h3><ul><li>text.js（纯文本）： <ul><li>使用 fs/promises.readFile 读取 UTF-8 文本。</li><li>去除 UTF-8 BOM（首字节 0xFEFF），避免影响 embedding 质量。</li></ul></li><li>pdf.js（PDF）： <ul><li>通过 createRequire 加载 CJS 包 pdf-parse，避免 ESM 直接 import 导致的调试分支问题。</li><li>读取二进制 Buffer，调用 pdf-parse 提取 data.text。</li></ul></li><li>office.js（Office）： <ul><li>docx：使用 mammoth.extractRawText 快速提取纯文本。</li><li>xlsx/xls：使用 xlsx 逐 sheet 转 CSV，并以“# SheetName”标题分隔，利于检索理解表格结构。</li><li>其他（pptx/odt/ods/rtf 等）：使用 officeparser.parseOffice 转为 AST 后导出文本。</li></ul></li></ul><pre class="mermaid">classDiagram
class TextParser {
+parse(filePath) string
}
class PdfParser {
+parse(filePath) string
}
class OfficeParser {
+parseDocx(filePath) string
+parseSpreadsheet(filePath) string
+parseGeneric(filePath) string
+parse(filePath) string
}
OfficeParser --&gt; TextParser : &quot;不直接使用&quot;
OfficeParser --&gt; PdfParser : &quot;不直接使用&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/text.js#L10-L14" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/text.js#L10-L14</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/pdf.js#L15-L19" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/pdf.js#L15-L19</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/office.js#L15-L55" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/office.js#L15-L55</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/text.js#L1-15" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/text.js#L1-15</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/pdf.js#L1-21" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/pdf.js#L1-21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/office.js#L1-56" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/office.js#L1-56</a></li></ul><h3 id="文本分块器-chunker-js" tabindex="-1">文本分块器（chunker.js） <a class="header-anchor" href="#文本分块器-chunker-js" aria-label="Permalink to &quot;文本分块器（chunker.js）&quot;">​</a></h3><ul><li>目标： <ul><li>在保持语义完整性的前提下，将长文本切分为适合嵌入模型的片段。</li><li>为 BM25 混合检索预留原文偏移（startPos/endPos）。</li></ul></li><li>关键参数： <ul><li>chunkSize：默认 400，范围限制在 [50, 2000]。</li><li>overlap：默认 80，最大不超过 chunkSize/2。</li><li>CHUNK_SIZE_WARN_LIMIT：超过此值会告警，防止被模型静默截断。</li></ul></li><li>断点优先级： <ul><li>优先在自然断点处收束：\\n\\n、\\n、句号、感叹号、问号、分号及其英文变体。</li><li>搜索区间为块后半段，从后往前找最近断点。</li></ul></li><li>边界处理： <ul><li>跳过块间空白，确保每个 chunk 非空。</li><li>重叠回退保证不会死循环：next = end - overlap，若 next ≤ start 则取 end。</li></ul></li><li>复杂度： <ul><li>时间复杂度 O(n)，其中 n 为文本长度；断点查找在最坏情况下为常数级多次扫描。</li><li>空间复杂度 O(k)，k 为生成的 chunk 数量。</li></ul></li></ul><pre class="mermaid">flowchart TD
S[&quot;开始&quot;] --&gt; Normalize[&quot;规范化换行&quot;]
Normalize --&gt; Clamp[&quot;clamp(chunkSize, overlap)&quot;]
Clamp --&gt; Warn{&quot;chunkSize &gt; 安全上限？&quot;}
Warn --&gt; |是| LogWarn[&quot;记录告警日志&quot;]
Warn --&gt; |否| Loop[&quot;遍历文本&quot;]
LogWarn --&gt; Loop
Loop --&gt; SkipWS[&quot;跳过空白&quot;]
SkipWS --&gt; SetEnd[&quot;end = min(start+chunkSize, n)&quot;]
SetEnd --&gt; FindBP{&quot;未到文末？&quot;}
FindBP --&gt; |是| BP[&quot;在后半段寻找最近断点&quot;]
FindBP --&gt; |否| Slice[&quot;切片&quot;]
BP --&gt; Slice
Slice --&gt; Push{&quot;chunk 非空？&quot;}
Push --&gt; |是| Add[&quot;加入结果数组&quot;]
Push --&gt; |否| NextStep[&quot;计算下一起点&quot;]
Add --&gt; NextStep
NextStep --&gt; More{&quot;pos &lt; n？&quot;}
More --&gt; |是| Loop
More --&gt; |否| Return[&quot;返回 chunks[]&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L9-L74" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L9-L74</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L37-L44" target="_blank" rel="noreferrer">agent/src/rag/config.js#L37-L44</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L37-L44" target="_blank" rel="noreferrer">agent/src/rag/config.js#L37-L44</a></li></ul><h3 id="配置与扩展名路由-config-js" tabindex="-1">配置与扩展名路由（config.js） <a class="header-anchor" href="#配置与扩展名路由-config-js" aria-label="Permalink to &quot;配置与扩展名路由（config.js）&quot;">​</a></h3><ul><li>解析器扩展名路由表 PARSER_ROUTES： <ul><li>.txt/.md/.json/.csv → text</li><li>.html/.htm → html</li><li>.pdf → pdf</li><li>.docx/.pptx/.xlsx/.xls → office</li></ul></li><li>默认分块配置 DEFAULT_CHUNK_CONFIG： <ul><li>chunkSize=400，overlap=80。</li></ul></li><li>安全上限 CHUNK_SIZE_WARN_LIMIT： <ul><li>500，超过将触发告警。</li></ul></li><li>RAG 根目录与环境变量： <ul><li>RAG_ROOT 可由 AI_HELPER_RAG_ROOT 覆盖，便于测试隔离或自定义数据目录。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L1-L70" target="_blank" rel="noreferrer">agent/src/rag/config.js#L1-L70</a></li></ul><h3 id="错误处理-errors-js" tabindex="-1">错误处理（errors.js） <a class="header-anchor" href="#错误处理-errors-js" aria-label="Permalink to &quot;错误处理（errors.js）&quot;">​</a></h3><ul><li>RagError： <ul><li>携带 code 与 params，便于上层 i18n 渲染。</li></ul></li><li>translateRagError： <ul><li>将任意 Error 转为 { error, code }，RagError 走 t(<code>rag.err_\${code}</code>, params) 翻译。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L1-L30</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>loader.js 依赖： <ul><li>path.extname/basename：路径处理。</li><li>config.PARSER_ROUTES：扩展名到解析器名称的映射。</li><li>errors.RagError：不支持格式的错误。</li></ul></li><li>parsers： <ul><li>text.js：fs/promises.readFile。</li><li>pdf.js：module.createRequire + pdf-parse（CJS）。</li><li>office.js：mammoth、xlsx、officeparser（按需 require/import）。</li></ul></li><li>chunker.js 依赖： <ul><li>config.CHUNK_SIZE_WARN_LIMIT：安全上限告警。</li></ul></li></ul><pre class="mermaid">graph LR
Loader[&quot;loader.js&quot;] --&gt; Routes[&quot;config.PARSER_ROUTES&quot;]
Loader --&gt; Errors[&quot;errors.RagError&quot;]
Loader --&gt; P_Text[&quot;parsers/text.js&quot;]
Loader --&gt; P_Pdf[&quot;parsers/pdf.js&quot;]
Loader --&gt; P_Office[&quot;parsers/office.js&quot;]
Chunker[&quot;chunker.js&quot;] --&gt; Config[&quot;config.CHUNK_SIZE_WARN_LIMIT&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L4-L14" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L4-L14</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L5-L16" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L5-L16</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L7-L8" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L7-L8</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-L76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L1-L30</a></li></ul><h2 id="性能与内存优化" tabindex="-1">性能与内存优化 <a class="header-anchor" href="#性能与内存优化" aria-label="Permalink to &quot;性能与内存优化&quot;">​</a></h2><ul><li>按需加载解析器： <ul><li>loader.js 中 PARSERS 使用箭头函数延迟 import，仅在需要时加载对应依赖，降低冷启动与常驻内存占用。</li></ul></li><li>大文件处理： <ul><li>PDF 与 Office 解析均先读取整个文件到内存（Buffer 或字符串），对于超大文件建议在上层做大小限制与分批处理。</li><li>chunker 对文本进行线性扫描，时间复杂度 O(n)，无额外复杂数据结构，内存占用与输出 chunk 数成正比。</li></ul></li><li>分块安全边界： <ul><li>chunkSize 被 clamp 到 [50, 2000]，且超过 CHUNK_SIZE_WARN_LIMIT 会告警，避免模型静默截断导致内容丢失。</li><li>overlap 控制在合理范围，避免重复过多影响检索效率。</li></ul></li><li>文本预处理： <ul><li>text.js 去除 UTF-8 BOM，提升 embedding 质量。</li><li>chunker 统一换行为 \\n，提高断点查找稳定性。</li></ul></li></ul><p>[本节为通用指导，无需特定文件引用]</p><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><ul><li>不支持的文件格式： <ul><li>现象：调用 loadDocument 抛出 RagError(&#39;unsupportedFormat&#39;, { ext })。</li><li>排查：检查文件扩展名是否在 PARSER_ROUTES 中；必要时新增路由映射。</li></ul></li><li>PDF 解析失败： <ul><li>现象：pdf-parse 报错或返回空文本。</li><li>排查：确认文件可读、非损坏 PDF；注意 pdf-parse 为 CJS，必须通过 createRequire 加载。</li></ul></li><li>Office 解析异常： <ul><li>现象：docx/xlsx/pptx 解析失败或文本为空。</li><li>排查：确认依赖已安装；xlsx 需逐 sheet 转 CSV；pptx 等走 officeparser。</li></ul></li><li>分块过大告警： <ul><li>现象：控制台输出 chunkSize 超过安全上限的警告。</li><li>排查：调整 chunkSize 至默认 400 附近，确保不超过 CHUNK_SIZE_WARN_LIMIT。</li></ul></li><li>错误国际化： <ul><li>现象：错误消息未翻译或显示原始 message。</li><li>排查：上层应使用 translateRagError(err, t) 将 RagError 转为可翻译对象。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L38-L47" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L38-L47</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/pdf.js#L15-L19" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/pdf.js#L15-L19</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/office.js#L50-L55" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/office.js#L50-L55</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L36-L41" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L36-L41</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L24-L29" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L24-L29</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>该文档处理与解析模块以 loader 为统一入口，通过扩展名路由到不同解析器，实现多格式文档到纯文本的统一转换；chunker 在此基础上提供稳定可控的分块能力，兼顾中文语义完整性与模型 token 上限。整体架构清晰、依赖按需加载、错误类型规范，便于扩展与维护。针对大文件场景，建议在上层增加大小限制与批处理策略，并结合 chunker 的安全上限告警进行调优。</p><p>[本节为总结性内容，无需特定文件引用]</p><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><h3 id="支持的文件格式列表" tabindex="-1">支持的文件格式列表 <a class="header-anchor" href="#支持的文件格式列表" aria-label="Permalink to &quot;支持的文件格式列表&quot;">​</a></h3><ul><li>文本类：.txt、.md、.json、.csv</li><li>HTML：.html、.htm</li><li>PDF：.pdf</li><li>Office：.docx、.pptx、.xlsx、.xls</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li></ul><h3 id="配置选项说明" tabindex="-1">配置选项说明 <a class="header-anchor" href="#配置选项说明" aria-label="Permalink to &quot;配置选项说明&quot;">​</a></h3><ul><li>RAG_ROOT：RAG 数据根目录，可通过环境变量 AI_HELPER_RAG_ROOT 覆盖。</li><li>DEFAULT_CHUNK_CONFIG：默认分块参数（chunkSize=400，overlap=80）。</li><li>CHUNK_SIZE_WARN_LIMIT：分块安全上限（500），超过将告警。</li><li>PARSER_ROUTES：解析器扩展名路由表，决定各扩展名对应的解析器名称。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L11-L18" target="_blank" rel="noreferrer">agent/src/rag/config.js#L11-L18</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L37-L44" target="_blank" rel="noreferrer">agent/src/rag/config.js#L37-L44</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li></ul>`,81)])])}const f=r(i,[["render",n]]);export{p as __pageData,f as default};
